package com.aegis.browser.web

import android.webkit.JavascriptInterface
import com.aegis.browser.BrowserActivity

/**
 * Receives blob/data downloads from the page. A one-time token, generated by the
 * native side for each download request, prevents arbitrary pages from writing
 * files through this bridge.
 */
class BlobBridge(private val activity: BrowserActivity) {

    @Volatile
    var pendingToken: String? = null

    @JavascriptInterface
    fun save(token: String, dataUrl: String, mime: String, name: String) {
        if (pendingToken == null || token != pendingToken) return
        pendingToken = null
        activity.runOnUiThread {
            activity.onBlobDownload(dataUrl, mime, name)
        }
    }
}
